private def toBlockType[BT](blockType: BT)(implicit bt: BlockTypeLike[BT]): BlockType =
  bt.toBlockType(this, blockType)

def ifThenElse[BT: BlockTypeLike](blockType: BT)(thenp: => Unit)(elsep: => Unit): Unit = {
  instrs += If(toBlockType(blockType))
  thenp
  instrs += Else
  elsep
  instrs += End
}

def ifThenElse()(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElse(BlockType.ValueType())(thenp)(elsep)

def ifThen[BT: BlockTypeLike](blockType: BT)(thenp: => Unit): Unit = {
  instrs += If(toBlockType(blockType))
  thenp
  instrs += End
}

def ifThen()(thenp: => Unit): Unit =
  ifThen(BlockType.ValueType())(thenp)

def block[A, BT: BlockTypeLike](blockType: BT)(body: LabelID => A): A = {
  val label = genLabel()
  instrs += Block(toBlockType(blockType), Some(label))
  val result = body(label)
  instrs += End
  result
}

def block[A]()(body: LabelID => A): A =
  block(BlockType.ValueType())(body)

def loop[A, BT: BlockTypeLike](blockType: BT)(body: LabelID => A): A = {
  val label = genLabel()
  instrs += Loop(toBlockType(blockType), Some(label))
  val result = body(label)
  instrs += End
  result
}

def loop[A]()(body: LabelID => A): A =
  loop(BlockType.ValueType())(body)

def whileLoop()(cond: => Unit)(body: => Unit): Unit = {
  loop() { loopLabel =>
    cond
    ifThen() {
      body
      instrs += Br(loopLabel)
    }
  }
}

def tryTable[A, BT: BlockTypeLike](blockType: BT)(clauses: List[CatchClause])(body: => A): A = {
  instrs += TryTable(toBlockType(blockType), clauses)
  val result = body
  instrs += End
  result
}

def tryTable[A]()(clauses: List[CatchClause])(body: => A): A =
  tryTable(BlockType.ValueType())(clauses)(body)

object FunctionBuilder {
  /** Typeclass for values that can be turned into a [[Types.BlockType]].
   *
   *  This factors out the various shorthands accepted by the structured
   *  control-flow helpers (`ifThen`, `block`, `loop`, `tryTable`, ...), so that
   *  each helper only needs a single generic overload plus a no-argument one.
   */
  sealed abstract class BlockTypeLike[-BT] {
    def toBlockType(fb: FunctionBuilder, blockType: BT): BlockType
  }

  object BlockTypeLike {
    implicit object ofBlockType extends BlockTypeLike[BlockType] {
      def toBlockType(fb: FunctionBuilder, blockType: BlockType): BlockType = blockType
    }

    implicit object ofType extends BlockTypeLike[Type] {
      def toBlockType(fb: FunctionBuilder, resultType: Type): BlockType =
        BlockType.ValueType(resultType)
    }

    implicit object ofFunctionType extends BlockTypeLike[FunctionType] {
      def toBlockType(fb: FunctionBuilder, sig: FunctionType): BlockType =
        fb.sigToBlockType(sig)
    }

    implicit object ofResultTypes extends BlockTypeLike[List[Type]] {
      def toBlockType(fb: FunctionBuilder, resultTypes: List[Type]): BlockType =
        fb.sigToBlockType(FunctionType(Nil, resultTypes))
    }
  }

